for (var entry : new ArrayList<>(bound.entrySet())) {
    Path p = entry.getKey();
    BoundCandidate b = entry.getValue();
    if (!Files.exists(p)) {
        b.missing++;
        if (b.missing >= 40) {
            bound.remove(p);
            known.remove(p);
        }
        continue;
    }
    b.missing = 0;
    long size;
    try {
        size = Files.size(p);
    } catch (IOException ex) {
        continue;
    }
    if (size <= 0)
        continue;
    if (size == b.lastSize)
        b.stable++;
    else {
        b.lastSize = size;
        b.stable = 0;
    }
    if (b.stable < 1 || now < b.nextAttemptAt)
        continue;
    if (!contextValidator.test(b.notePath, b.generation)) {
        markManual(p);
        bound.remove(p);
        quarantineUntil = now + 2000;
        continue;
    }
    IngestResult result = ingester.apply(p, b);
    if (result == IngestResult.OK) {
        known.add(p);
        bound.remove(p);
        AudioFeedback.success();
    } else if (result == IngestResult.STALE) {
        markManual(p);
        bound.remove(p);
        quarantineUntil = now + 2000;
    } else
        b.nextAttemptAt = now + 1000;
}

