new SwingWorker<PreserveSystemAudioObservationFeature.RecordingTarget, Void>() {

    @Override
    protected PreserveSystemAudioObservationFeature.RecordingTarget doInBackground() throws Exception {
        return preserveSystemAudioObservationFeature.cancel();
    }

    @Override
    protected void done() {
        audioBusy = false;
        audioButton.setText("Начать звук");
        audioButton.setEnabled(true);
        audioStateLabel.setText("");
        try {
            PreserveSystemAudioObservationFeature.RecordingTarget result = get();
            if (!result.equals(expected))
                throw new IOException("Audio cancel target changed unexpectedly.");
            if (Objects.equals(result.folder(), currentFolder) && Objects.equals(result.note(), currentNote))
                loadCurrentNote();
            showStatus("Аудиозапись отменена; незавершённый AudioElement удалён");
        } catch (Exception ex) {
            refreshTrackedAudioIfVisible();
            showWorkerError("Не удалось полностью отменить аудиозапись", ex);
        }
    }
}

new SwingWorker<ExportFolderForSharingFeature.FolderExportOutcome, Void>() {

    @Override
    protected ExportFolderForSharingFeature.FolderExportOutcome doInBackground() throws Exception {
        return exportFolderForSharingFeature.exportFolderToDirectory(folder, destinationDirectory);
    }

    @Override
    protected void done() {
        exportButton.setEnabled(true);
        try {
            ExportFolderForSharingFeature.FolderExportOutcome result = get();
            showStatus("Архив папки создан: " + result.destination().getFileName());
            showFolderExportOutcome(result);
        } catch (InterruptedException ex) {
            Thread.currentThread().interrupt();
            showStatus("Создание архива прервано");
        } catch (java.util.concurrent.ExecutionException ex) {
            Throwable cause = ex.getCause();
            if (cause instanceof IOException io)
                error(io);
            else
                error(new IOException(cause == null ? ex : cause));
        }
    }
}

new SwingWorker<AudioElement, Void>() {

