        } catch (Exception ex) {
            audioButton.setText("Начать звук");
            audioButton.setEnabled(true);
            audioStateLabel.setText("");
            refreshTrackedAudioIfVisible();
            showWorkerError("Не удалось начать аудиозапись", ex);
        }
    }
}

new SwingWorker<PreserveSystemAudioObservationFeature.StopOutcome, Void>() {

    @Override
    protected PreserveSystemAudioObservationFeature.StopOutcome doInBackground() throws Exception {
        return preserveSystemAudioObservationFeature.stop();
    }

    @Override
    protected void done() {
        audioBusy = false;
        audioButton.setText("Начать звук");
        audioButton.setEnabled(true);
        audioStateLabel.setText("");
        try {
            PreserveSystemAudioObservationFeature.StopOutcome result = get();
            if (!result.elementId().equals(expected.elementId()) || !result.folder().equals(expected.folder()) || !result.note().equals(expected.note())) {
                throw new IOException("Audio session target changed unexpectedly.");
            }
            if (result.finalized()) {
                if (Objects.equals(result.folder(), currentFolder) && Objects.equals(result.note(), currentNote)) {
                    loadCurrentNote();
                    selectElementById(result.elementId());
                }
                showStatus("Аудио завершено → " + result.folder() + " / " + result.note());
                return;
            }
            refreshTrackedAudioIfVisible();
            String path = result.retainedWav() == null ? "—" : result.retainedWav().toAbsolutePath().normalize().toString();
            JOptionPane.showMessageDialog(MainHelperWindow.this, result.warning() + "\n\nФайл сохранён:\n" + path + "\n\nRecording AudioElement оставлен незавершённым.", "gd-cap — WAV сохранён", JOptionPane.WARNING_MESSAGE);
            showStatus("WAV сохранён, AudioElement остался незавершённым: " + path);
        } catch (Exception ex) {
            refreshTrackedAudioIfVisible();
            showWorkerError("Не удалось завершить аудиозапись", ex);
        }
    }
}

